package com.campusvibe.controller;
import com.campusvibe.dto.*; import com.campusvibe.entity.*; import com.campusvibe.repository.UserRepository; import com.campusvibe.security.JwtService; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { final UserRepository users; final PasswordEncoder enc; final JwtService jwt; public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;enc=e;jwt=j;}
@PostMapping("/register") public ResponseEntity<?> register(@RequestBody RegisterRequest r){if(users.findByEmail(r.email()).isPresent())return ResponseEntity.badRequest().body(Map.of("message","Email already registered"));User u=new User();u.name=r.name();u.email=r.email();u.password=enc.encode(r.password());u.role=Role.STUDENT;u.studentId=r.studentId();u.department=r.department();u.year=r.year();u.phone=r.phone();users.save(u);return ResponseEntity.ok(login(new AuthRequest(r.email(),r.password())));}
@PostMapping("/login") public ResponseEntity<?> login(@RequestBody AuthRequest r){var o=users.findByEmail(r.email());if(o.isEmpty()||!enc.matches(r.password(),o.get().password))return ResponseEntity.status(401).body(Map.of("message","Invalid credentials"));User u=o.get();return ResponseEntity.ok(new AuthResponse(jwt.generate(u.email,u.role.name()),u.id,u.name,u.email,u.role.name()));}
}
